import { FLOW_LIMITS, ID_PATTERN } from "./limits";

// The interactive reply identifier contract (V3.2 section E): `b1.<promptToken>.<optionKey>`.
//
// The prompt token is generated by the RUNTIME per prompt (Phase 08E, 128 random bits, base64url); the validator and these
// helpers never create one. Phase 08B evaluates replies; this file only defines and checks the syntax. Nothing here assumes
// that Meta supplies reply context.

export const REPLY_ID_PREFIX = "b1";
/** 16 random bytes in base64url without padding. */
export const PROMPT_TOKEN_PATTERN = /^[A-Za-z0-9_-]{22}$/;
export const REPLY_ID_PATTERN = /^b1\.[A-Za-z0-9_-]{22}\.[a-z][a-z0-9_]{0,31}$/;
/** 3 (`b1.`) + 22 (token) + 1 (`.`) + 32 (longest option key). Within the 64-character limit we set and Meta's 256 / 200. */
export const REPLY_ID_MAX_LENGTH = 3 + 22 + 1 + FLOW_LIMITS.identifierMax;

export function isPromptToken(value: unknown): value is string {
  return typeof value === "string" && PROMPT_TOKEN_PATTERN.test(value);
}

export function isReplyId(value: unknown): value is string {
  return (
    typeof value === "string" && value.length <= REPLY_ID_MAX_LENGTH && REPLY_ID_PATTERN.test(value)
  );
}

export type ParsedReplyId = { readonly promptToken: string; readonly optionKey: string };

/** The token and option key of a well-formed reply id; null for anything else (never throws, never partially parses). */
export function parseReplyId(value: unknown): ParsedReplyId | null {
  if (!isReplyId(value)) return null;
  const [, promptToken, optionKey] = value.split(".");
  return promptToken !== undefined && optionKey !== undefined ? { promptToken, optionKey } : null;
}

/** Joins a token supplied by the caller and an option key; null when either part is malformed. */
export function formatReplyId(promptToken: string, optionKey: string): string | null {
  if (!isPromptToken(promptToken) || !ID_PATTERN.test(optionKey)) return null;
  return `${REPLY_ID_PREFIX}.${promptToken}.${optionKey}`;
}
